<?php declare(strict_types=1); function e(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); } function site_data(string $n): array { static $c=[]; if (basename($n)!==$n || !preg_match('/^[a-z0-9-]+\.json$/',$n)) throw new InvalidArgumentException('Invalid data filename'); if(isset($c[$n])) return $c[$n]; $p=DATA_ROOT.'/'.$n; if(!is_file($p)) throw new RuntimeException('Site content unavailable'); $d=json_decode((string)file_get_contents($p),true,512,JSON_THROW_ON_ERROR); if(!is_array($d)) throw new RuntimeException('Invalid site content'); return $c[$n]=$d; } function site_config(): array { return site_data('site.json'); } function canonical_url(string $p): ?string { $b=rtrim((string)(site_config()['production_url']??''),'/'); return preg_match('#^https://#',$b)?$b.'/'.ltrim($p,'/'):null; } function external_url(mixed $v): ?string { return is_string($v)&&filter_var($v,FILTER_VALIDATE_URL)&&preg_match('#^https?://#i',$v)?$v:null; }